shots.draw_js:
clearScene();setBig(null);
setEq("$$\\mathrm{Regret}(T)=\\sum_{t=1}^{T}\\big[\\,Q(a^*)-Q(a_t)\\,\\big]$$","top");
note("这个我们不知道",480,330,"r lg");
note("这个也不知道",840,330,"r lg");
setCap("要证的东西里有<b>两个不可观测的量</b> —— 而 a* 我们压根不知道是哪个。");

clearScene();setEq(null);
setBig("a* 不知道，就没法算","要证界，总得先知道要比什么吧");
setCap("不需要<b>算出</b> Q(a*)。只需要把它<b>替换成一个已知的上界</b>。");

clearScene();setBig(null);
setEq("$$U_t(a_t)\\ \\ge\\ Q(a^*)$$","top");
note("情形一：a_t 就是 a*",420,330,"b lg");
note("情形二：a_t 不是 a*",880,330,"v lg");
note("两种都成立",640,395,"g lg");
setCap("<b>核心引理</b>：只要置信区间没失效，选中的臂的上界<b>压住</b>最优臂的真值。");

clearScene();setBig(null);
setEq("$$\\sum_t\\big[Q(a^*)-Q(a_t)\\big]=\\sum_t\\big[U_t(a_t)-Q(a_t)\\big]+\\underbrace{\\sum_t\\big[Q(a^*)-U_t(a_t)\\big]}_{\\le\\,0}$$","top");
note("加一项减一项",420,340,"y lg");
note("这一整块 ≤ 0，丢掉",900,340,"g lg");
setCap("<b>加减同一项</b>，再用引理把后半块整个丢掉 —— <b>a\* 就此消失</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"算出 Q(a*)",sub:"做不到",state:"dead"},
  {label:"替换成上界",sub:"做得到",state:"on"},
  {label:"方向安全",sub:"只会更松",state:"on"}]});
note("证上界不需要知道确切值",640,420,"y");
setCap("<b>指名反驳</b>：不是算出 a*，是<b>把它替换掉</b>，并证明替换只让界变松。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"一个区间",sub:"1−δ",state:"on"},
  {label:"m 个臂",sub:"？",state:"dead"},
  {label:"所有时刻",sub:"？",state:"dead"}]});
note("上一集的前提在这里兑现",640,420,"y");
setCap("上一集的引理要求「<b>所有</b>区间<b>同时</b>成立」。这一集算它值多少钱。");

clearScene();setEq(null);
setBig("每个 95%，合起来还是 95%","都是同一套区间嘛");
setCap("失败概率是<b>相加</b>的。m 个臂 T 个时刻，固定 δ 会累成 <b>Tmδ</b>。");

clearScene();setBig(null);
setEq("$$\\text{第 }t\\text{ 步的失败预算}=\\frac{\\delta}{t^2}$$","top");
note("越往后要求越严",640,330,"y lg");
setCap("改法只有一处：让每一步的失败预算<b>随 t 按 1/t² 衰减</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[1.549768,1.634984,1.644834,1.644933],
  x:330,y:350,w:620,h:150,max:2.0,
  label:function(i){return ["10 项","100","10⁴","10⁶"][i];},
  cls:function(i){return i===3?"g":"y";},
  fmt:function(v){return v.toFixed(4);}});
note("Σ 1/t² 的部分和",640,392,"sm");
setCap("加到无穷也只有 <b>π²/6 = 1.6449</b>。<b>小于 2</b> —— 总失败 < <b>2mδ</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"固定 δ",sub:"累成 Tmδ",state:"dead"},
  {label:"δ/t²",sub:"总和 < 2mδ",state:"on"},
  {label:"与 T 无关",sub:"永远成立",state:"on"}]});
note("1 − 2mδ 里的 2 从这来",640,420,"y");
setCap("<b>指名反驳</b>：失败概率<b>相加</b>。让它按 1/t² 衰减，<b>总和才有界</b>。");

clearScene();setBig(null);
setEq("$$\\mathrm{Regret}(T)\\ \\le\\ \\sum_{t=1}^{T}\\big[U_t(a_t)-Q(a_t)\\big]\\ \\le\\ \\sum_{t=1}^{T} 2\\,u_t(a_t)$$","top");
note("只剩下半径的和",640,330,"g lg");
setCap("三块拼完，遗憾被压成一句话：<b>把所有半径加起来</b>。");

clearScene();setEq(null);
setBig("n 和 t 差不多","都是时间，都在往上涨");
setCap("它们在半径里<b>方向相反</b>：n 让半径<b>缩</b>，t 让半径<b>涨</b>。");

clearScene();setBig(null);
setEq("$$\\sum_{n=1}^{N}\\frac{1}{\\sqrt{n}}\\ \\le\\ 2\\sqrt{N}$$","top");
note("N=10⁴ 时 198.54 对 200",640,330,"g lg");
setCap("先把 t 冻住（放大成 T），剩下的就是<b>每个臂自己的 1/√n 求和</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[223.61,203.95,141.42,103.98],
  x:330,y:350,w:620,h:150,max:250,
  label:function(i){return ["均分","偏斜","两臂","独大"][i];},
  cls:function(i){return i===0?"r":"b";},
  fmt:function(v){return v.toFixed(0);}});
note("Σ√N_a，T=10⁴ m=5",640,392,"sm");
setCap("最坏情形是<b>均分</b>：Σ√N_a 在均分时最大 = <b>√(mT)</b> = 223.61。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2],step:560,vals:[22.5,8.0,2.8],
  x:400,y:350,w:480,h:150,max:26,
  label:function(i){return ["T=10³","10⁴","10⁵"][i];},
  cls:function(i){return i===2?"g":"y";},
  fmt:function(v){return v.toFixed(1)+"%";}});
note("遗憾占 T 的比例",640,392,"sm");
setCap("<b>指名反驳</b>：n 缩 t 涨，方向相反。次线性 = <b>占比</b>在掉，不是遗憾在掉。");
